from pathlib import Path
import hashlib,json
root=Path.cwd(); base=root.parent/'checks/parametric'
def digest(value):
 return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
reports={}
for name in ('suite','seeded'):
 folder=base/name; manifest=json.loads((folder/'manifest.json').read_text())
 for path,expected in manifest['files'].items():
  assert hashlib.sha256((folder/path).read_bytes()).hexdigest()==expected, path
 receipt=json.loads((folder/'private/receipt.json').read_text())
 for path,expected in receipt['source_hashes'].items():
  assert hashlib.sha256((root/path).read_bytes()).hexdigest()==expected, path
 for key,expected in receipt['program_hashes'].items():
  assert hashlib.sha256((folder/'private/rules'/f'{key}.rkt').read_bytes()).hexdigest()==expected
 executions=[json.loads(line) for line in (folder/'private/executions.jsonl').read_text().splitlines()]
 bound={}
 for row in executions:
  assert digest(row['input'])==row['input_sha256']
  assert digest(row['output'])==row['output_sha256']
  assert hashlib.sha256(row['expression'].encode()).hexdigest()==row['expression_sha256']
  bound[row['program_sha256'],row['input_sha256']]=row['output']
 episodes=json.loads((folder/'private/episodes.json').read_text()); labels=0; inputs_by_seed={}
 for ep in episodes:
  public=json.loads((folder/ep['public_path']).read_text())
  assert set(public)=={'train','test'} and all(set(p)=={'input','output'} for p in public['train']) and all(set(p)=={'input'} for p in public['test'])
  assert digest(public)==ep['public_sha256'] and public==ep['public']
  key=f"{ep['parameters']['axis']}-{ep['parameters']['output_color']}"
  assert ep['program']==(folder/'private/rules'/f'{key}.rkt').read_text()
  assert ep['program_sha256']==receipt['program_hashes'][key]
  pairs=ep['train']+ep['test']; inputs=[pair['input'] for pair in pairs]
  if ep['seed'] in inputs_by_seed: assert inputs_by_seed[ep['seed']]==inputs
  inputs_by_seed[ep['seed']]=inputs
  for pair in pairs:
   assert bound[ep['program_sha256'],digest(pair['input'])]==pair['output']; labels+=1
  for rival in ep['rival_results']:
   assert rival['status']=='refuted_by_demonstrations'
   predictions=rival['predictions']['train']+rival['predictions']['test']
   for pair,prediction in zip(pairs,predictions):
    assert bound[rival['program_sha256'],digest(pair['input'])]==prediction; labels+=1
   differences=[i for i,(pair,prediction) in enumerate(zip(ep['train'],rival['predictions']['train'])) if pair['output']!=prediction]
   assert differences==rival['differing_train_indices'] and differences
  assert public['train']==ep['train'] and public['test']==[{'input':pair['input']} for pair in ep['test']]
 reports[name]={'status':'passed','episode_count':len(episodes),'manifest_files_verified':len(manifest['files']),'source_files_verified':len(receipt['source_hashes']),'retained_output_bindings_verified':labels,'actual_execution_rows_verified':len(executions),'receipt_sha256':hashlib.sha256((folder/'private/receipt.json').read_bytes()).hexdigest()}
result={'status':'passed','scope':'prototype evidence integrity; no new label execution','reports':reports}
(base/'integrity.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result,sort_keys=True))
